247	  ngOnInit() {
248	
249	    this.setCurrentCandidate(null);
250	    this.loggedInUser = this.authenticationService.getLoggedInUser();
251	    if (this.isSavedSearch()) {
252	       this.savedListCandidateService.getSelectionListCandidates(this.candidateSource.id).subscribe(
253	        (result) => {
254	          this.selectedCandidates = result;
255	          this.selectedCandidatesChange.emit(result);
256	        },
257	        (error) => {
258	          this.error = error;
259	        }
260	      )
261	    } else {
262	      this.selectedCandidates = [];
263	    }
264	
265	    this.statuses = [
266	      ReviewStatus[ReviewStatus.rejected],
267	      ReviewStatus[ReviewStatus.verified],
268	      ReviewStatus[ReviewStatus.unverified]
269	    ];
270	
271	    //Different use of searchForm depending on whether saved search or saved list
272	
273	    if (isSavedSearch(this.candidateSource)) {
274	      const reviewable = this.candidateSource.reviewable;
275	      this.searchInResultsForm = this.fb.group({
276	        statusesDisplay: [reviewable ? defaultReviewStatusFilter: []],
277	      });
278	    }
279	    if (isSavedList(this.candidateSource)) {
280	      this.searchInResultsForm = this.fb.group({
281	        keyword: [''],
282	        showClosedOpps: [this.showClosedOpps]
283	      });
284	      this.subscribeToFilterChanges();
285	
286	      this.doNumberOrNameSearch = (text$: Observable<string>) =>
287	        text$.pipe(
288	          debounceTime(300),
289	          distinctUntilChanged(),
290	          tap(() => {
291	            this.error = null
292	          }),
293	          switchMap(candidateNumberOrName =>
294	            this.candidateService.findByCandidateNumberOrName(
295	              {candidateNumberOrName: candidateNumberOrName, pageSize: 10}).pipe(
296	              tap(() => this.searchFailed = false),
297	              map(result => result.content),
298	              catchError(() => {
299	                this.searchFailed = true;
300	                return of([]);
301	              }))
302	          )
303	        );
304	    }
305	  }
306	
307	  get pluralType() {
308	     return isSavedSearch(this.candidateSource) ? "searches" : "lists";
309	  }
310	
