332	  subscribeToFilterChanges(): void {
333	    this.searchInResultsForm.valueChanges
334	      .pipe(
335	        debounceTime(800),
336	        distinctUntilChanged()
337	      )
338	      .subscribe(() => {
339	        this.filterSearch = true;
340	        this.saveShowClosedOpps();
341	        this.doSearch(true);
342	      });
343	  }
344	
345	  private saveShowClosedOpps(): void {
346	    const showClosedOppsValue = this.searchInResultsForm.get('showClosedOpps').value;
347	    this.localStorageService.set(this.savedListStateKey() + this.showClosedOppsSuffix, showClosedOppsValue.toString());
348	  }
349	
350	  /**
351	   * Restores candidate profile search card to previous px distance from top if > 0.
352	   */
353	  public setSearchCardScrollTop() {
354	    // Starting at 0 is default behaviour so no action needed in that case.
355	    if (this.searchCardScrollTop > 0) {
356	      // The card has to fully render before scrolling, so a short delay is necessary.
357	      setTimeout(() => {
358	        this.searchCard.scrollTo({ top: this.searchCardScrollTop, behavior: 'smooth' });
359	      }, 200)
360	    }
361	  }
362	
363	  ngOnChanges(changes: SimpleChanges): void {
364	    //If we get both a source change and a request change, do the source
365	    //change in preference to the request change because the source change
366	    //in that case will be a saved search and it will load a new search request
367	    //anyway - being the search request associated with the saved search.
368	
369	    if (changes.candidateSource) {
370	      if (changes.candidateSource.previousValue !== changes.candidateSource.currentValue) {
371	        if (this.candidateSource) {
372	
373	          //Set the selected fields to be displayed.
374	          this.loadSelectedFields();
375	
376	          //Retrieve the list previously used for saving selections from this
377	          // source (if any)
378	          this.restoreTargetListFromCache();
379	          this.doSearch(true);
380	          // Set the selected candidates (List only) to null when changing candidate source.
381	          this.selectedCandidates = [];
382	
383	          this.loadServiceList();
384	        }
385	      }
386	    }
387	
388	    // If there is a search request associated (saved search view) and the saved search request changes, update the search.
389	    if (changes.searchRequest) {
390	      if (changes.searchRequest.previousValue !== changes.searchRequest.currentValue) {
391	        if (this.searchRequest) {
392	          //A new search request has to clear the page number.
393	          //Old page number is no longer relevant with a new search.
394	          this.pageNumber = 1;
395	          this.updatedSearch();
396	        }
397	      }
398	    }
399	    // If the selected candidates is cleared via the parent define search component, trigger a refresh to update the selects.
400	    if (changes.selectedCandidates && changes.selectedCandidates.currentValue?.length == 0 && !changes.selectedCandidates.firstChange) {
401	      this.doSearch(true);
402	    }
403	  }
404	
405	  isSelected(candidate: Candidate): boolean {
406	    let selected: boolean;
407	    if (isSavedSearch(this.candidateSource)) {
408	      selected = candidate.selected;
409	    } else {
410	      selected = indexOfHasId(candidate.id, this.selectedCandidates) >= 0;
411	    }
412	    return selected;
413	  }
414	
415	  /**
416	   * True if any candidates are currently selected.
417	   */
418	  isSelection(): boolean {
419	    return this.selectedCandidates != null && this.selectedCandidates.length > 0;
420	  }
421	
422	  ngOnDestroy(): void {
423	    if (this.subscription) {
424	      this.subscription.unsubscribe();
425	    }
426	  }
427	
428	  /**
429	   * This is called when an existing search is being modified - ie a search field has changed.
430	   * @private
431	   */
432	  private updatedSearch() {
433	    this.results = null;
434	    this.error = null;
435	    this.searching = true;
436	    const request = this.searchRequest;
437	
438	    //Guard against the case where we have a text sort where there is no query string.
439	    let queryString = request.simpleQueryString;
440	    const haveSimpleQueryString: boolean =  queryString != null && queryString.trim().length > 0;
441	    if (!haveSimpleQueryString && this.sortField === "text_match") {
442	      //Text sort when there is no query string does not make sense.
443	      //So revert to standard id sort.
444	      this.sortField = "id";
445	      this.sortDirection = "DESC";
446	    }
447	
448	    //Search passed in externally will not have current reviewStatusFilter applied
449	    //because that is only managed by this component. So fill it in.
450	    if (this.isReviewable()) {
451	      request.reviewStatusFilter = this.reviewStatusFilter;
452	    }
453	
454	    request.pageNumber = this.pageNumber - 1;
455	    request.pageSize = this.pageSize;
456	    request.sortFields = [this.sortField];
457	    request.sortDirection = this.sortDirection;
458	    request.dtoType = this.searchDetail;
459	
460	    this.subscription = this.candidateService.search(request, this.useOldFetch).subscribe(
461	      results => {
462	        this.results = results;
463	        this.cacheResults();
464	        this.searching = false;
465	      },
466	      error => {
467	        this.error = error;
468	        this.searching = false;
469	      });
470	  }
471	
472	  doSearch(refresh: boolean, usePageNumber = true) {
473	    let done = this.checkCache(refresh, usePageNumber);
474	
475	    if (!done) {
476	      /*
477	       * Fetch results from the server rather than from any local cache.
478	       * <p/>
479	       * This component is used in two ways:
480	       * - To display saved lists
481	       * - To display saved searches.
482	       * This affects the way that a refresh is done.
483	       *
484	       * For saved lists, it is simply going to the server requesting the requested
485	       * page of the list.
486	       *
487	       * For saved searches, it is made more complicated because saved searches
488	       * can be displayed with details of the exact search, which are available
489	       * for the user to modify if they wish - thus changing the search.
490	       * But those changes are only stored on the server when the user clicks on
491	       * Update Search.
492	       * So, at any time there are potentially two different searches:
493	       * - the one stored on the server
494	       * - the modified one on the browser
495	       *
496	       * The results displayed to the user looking at a saved search are those
497	       * which incorporate their local browser changes
498	       *
499	       * So... when we want to refresh a saved search, we don't want to use the
500	       * version stored on the server. But with a saved list we do.
501	       */
502	
503	      //If we are being driven by a manually modifiable search request (eg someone has changed the
504	      //search parameters and clicked on the Apply button) submit that search.
505	      if (this.searchRequest) {
506	        this.updatedSearch()
507	      } else {
508	        //Save the current candidate selection, then set it to null while we are searching.
509	        //Then we restore it at the end of the search. This means that anything displaying
510	        //info on the current selection will update its data.
511	        const saveCurrentCandidate = this.currentCandidate;
512	        this.setCurrentCandidate(null);
513	
514	        //Run the saved list or saved search as stored on the server.
515	        this.performSearch(
516	          this.pageSize,
517	          this.searchDetail,
518	          this.keyword,
519	          this.showClosedOpps).subscribe(() => {
520	          // Restore the selection prior to the search using the updated results (otherwise updated fields won't appear)
521	          const updatedCurrentCandidate = this.results.content.find(c => c.id == saveCurrentCandidate?.id);
522	          this.setCurrentCandidate(updatedCurrentCandidate);
523	          }, error => {
524	            // Error is already displayed in the UI
525	          }
526	        );
527	      }
528	    }
529	  }
530	
531	  setCurrentCandidate(candidate: Candidate) {
532	    this.currentCandidate = candidate;
533	    if (candidate && isSavedSearch(this.candidateSource)) {
534	      this.savedSearchSelectionChange = candidate.selected;
535	    }
536	    this.candidateSelection.emit(candidate);
537	  }
538	
539	  selectCandidate(candidate: Candidate) {
540	    // Save scrollbar px distance from top on previous candidate profile search card, if any.
541	    if (this.currentCandidate) {
542	      this.searchCard = document.querySelector('.profile');
543	      this.searchCardScrollTop = this.searchCard.scrollTop;
544	    }
545	    this.setCurrentCandidate(candidate);
546	  }
547	
548	  onReviewStatusChange() {
549	    this.doSearch(true);
550	  }
551	
552	  toggleFetch() {
553	    this.useOldFetch = !this.useOldFetch;
554	    this.doSearch(true);
555	  }
556	
557	  toggleSort(column: string, defaultSortDirection: string = 'ASC') {
558	    super.toggleSort(column, defaultSortDirection);
559	    this.doSearch(true);
560	  }
561	
562	  importCandidates() {
563	
564	    if (isSavedList(this.candidateSource)) {
565	
566	      const fileSelectorModal = this.modalService.open(FileSelectorComponent, {
567	        centered: true,
568	        backdrop: 'static'
569	      })
570	
571	      fileSelectorModal.componentInstance.validExtensions = ['csv', 'txt'];
572	      fileSelectorModal.componentInstance.maxFiles = 1;
573	      fileSelectorModal.componentInstance.closeButtonLabel = "Import";
574	      fileSelectorModal.componentInstance.title = "Select file containing candidate numbers";
575	      fileSelectorModal.componentInstance.instructions = "Select a file with one of the above " +
576	        "extensions which contains a candidate number at the start of each line. " +
577	        "This will work for a spreadsheet that has been exported in csv format as long as " +
578	        "candidate numbers are in the first column of the spreadsheet. " +
579	        "Other data in the spreadsheet will be ignored. Any header line will also be ignored.";
580	
581	      fileSelectorModal.result
582	      .then((selectedFiles: File[]) => {
583	        this.doImport(selectedFiles);
584	      })
585	      .catch(() => { /* Isn't possible */ });
586	    }
587	  }
588	
589	  private doImport(files: File[]) {
590	    const formData: FormData = new FormData();
591	    formData.append('file', files[0]);
592	
593	    this.error = null;
594	    this.importing = true;
595	    this.savedListCandidateService.mergeFromFile(this.candidateSource.id, formData).subscribe(
596	      result => {
597	        this.importing = false;
598	        this.doSearch(true);
599	      },
600	      error => {
601	        this.error = error;
602	        this.importing = false;
603	      }
604	    )
605	  }
606	
607	  exportCandidates() {
608	    if (this.results.totalElements > 5000) {
609	      const csvError: string = "Spreadsheet exports are currently capped at 5,000 candidates — please " +
610	        "contact a TC admin if if this limit will negatively impact your work."
611	      this.error = csvError
612	      throw new Error(csvError)
613	    }
614	    this.exporting = true;
615	
616	    //Create the appropriate request
617	    let request;
618	    let reviewable = false;
619	    if (isSavedSearch(this.candidateSource)) {
620	      reviewable = this.candidateSource.reviewable;
621	      request = new SavedSearchGetRequest();
622	    } else {
623	      request = new SavedListGetRequest();
624	    }
625	
626	    //Note: The page number and size are ignored in this call (all records are exported).
627	    //Only the sort fields are processed.
628	    request.sortFields = [this.sortField];
629	    request.sortDirection = this.sortDirection;
630	    if (reviewable) {
631	      request.reviewStatusFilter = this.reviewStatusFilter;
632	    }
633	
634	    this.candidateSourceCandidateService.export(this.candidateSource, request).subscribe(
635	      result => {
636	        const options = {type: 'text/csv;charset=utf-8;'};
637	        const filename = 'candidates.csv';
638	        this.createAndDownloadBlobFile(result, options, filename);
639	        this.exporting = false;
640	      },
641	      err => {
642	        const reader = new FileReader();
643	        const _this = this;
644	        reader.addEventListener('loadend', function () {
645	          if (typeof reader.result === 'string') {
646	            const errorObj = JSON.parse(reader.result);
647	            const csvExportErrorModal = _this.modalService.open(TcModalComponent, {});
648	            csvExportErrorModal.componentInstance.title = 'Export Failed';
649	            csvExportErrorModal.componentInstance.icon = 'fas fa-triangle-exclamation';
650	            csvExportErrorModal.componentInstance.actionText = 'Retry';
651	            csvExportErrorModal.componentInstance.message =
652	              "CSV download error: " + "'" + errorObj.message + "'";
