746	  createAndDownloadBlobFile(body, options, filename) {
747	    const blob = new Blob([body], options);
748	    if ('msSaveBlob' in navigator) {
749	      // IE 10+
750	      // @ts-ignore
751	      navigator.msSaveBlob(blob, filename);
752	    } else {
753	      const link = document.createElement('a');
754	      // Browsers that support HTML5 download attribute
755	      if (link.download !== undefined) {
756	        const url = URL.createObjectURL(blob);
757	        link.setAttribute('href', url);
758	        link.setAttribute('download', filename);
759	        link.style.visibility = 'hidden';
760	        document.body.appendChild(link);
761	        link.click();
762	        document.body.removeChild(link);
763	      }
764	    }
765	  }
