893	  onSelectionChange(candidate: Candidate, selected: boolean) {
894	    //Record change
895	    candidate.selected = selected;
896	    //Update cache
897	    this.cacheResults();
898	
899	    if (isSavedSearch(this.candidateSource)) {
900	      //Saved search selection change
901	
902	      if (candidate.contextNote && !selected) {
903	        //They have a context note which they will lose if they deselect.
904	        //Ask for confirmation.
905	        const confirmation = this.modalService.open(ConfirmationComponent, {
906	          centered: true,
907	          backdrop: 'static'
908	        });
909	        confirmation.componentInstance.message =
910	          'You will lose the context note for ' + candidate.user.firstName +
911	          ' if you deselect this. Are you sure?';
912	        confirmation.result
913	          .then((confirmed: boolean) => {
914	            if (confirmed) {
915	              //Clear local copy of note
916	              //Note that this does not trigger an update through to the
917	              //contextNote component.
918	              //That is why we use the savedSearchSelectionChange variable
919	              //which is passed down as an input to the contextNote component
920	              //and can trigger an action which updates the local contextNote
921	              //form field.
922	              candidate.contextNote = null;
923	              this.savedSearchSelectionChange = false;
924	              this.doSavedSearchSelection(candidate, selected);
925	            } else {
926	              //Unconfirmed, reinstate as selected
927	              candidate.selected = true;
928	            }
929	          })
930	          .catch(() => {
931	            //Unconfirmed, reinstate as selected
932	            candidate.selected = true;
933	          });
934	      } else {
935	        this.savedSearchSelectionChange = selected;
936	        this.doSavedSearchSelection(candidate, selected);
937	      }
938	    }
939	    //Maintain local candidate selections
940	    if (selected) {
941	      this.selectedCandidates.push(candidate);
942	    } else {
943	      this.selectedCandidates = this.selectedCandidates.filter(c => c.id !== candidate.id);
944	    }
945	    this.selectedCandidatesChange.emit(this.selectedCandidates);
946	  }
