1016	  /**
1017	   * Selected becomes unselected and vice versa.
1018	   * <p/>
1019	   * Note that this only works for saved lists.
1020	   * If it is called on a saved search it will do nothing.
1021	   */
1022	  swapSelection() {
1023	    if (isSavedList(this.candidateSource)) {
1024	
1025	      //First of all, get all candidates in this list from the server.
1026	      let request = new SavedListGetRequest();
1027	      request.keyword = this.keyword;
1028	      request.showClosedOpps = this.showClosedOpps;
1029	
1030	      this.searching = true;
1031	      this.error = null;
1032	      this.candidateSourceCandidateService.search(this.candidateSource, request).subscribe(
1033	        (candidates: Candidate[]) => {
1034	          //Now do the actual swap
1035	          this.doSwapSelection(candidates)
1036	          this.searching = false;
1037	        },
1038	        error => {
1039	          this.error = error;
1040	          this.searching = false;
1041	        });
1042	    }
1043	  }
