1045	  /**
1046	   * Selected becomes unselected and vice versa.
1047	   * <p/>
1048	   * Note: only works for saved lists - not saved sources.
1049	   * @param candidates All candidates
1050	   */
1051	  private doSwapSelection(candidates: Candidate[]) {
1052	    //This will contain the new selection
1053	    const newSelectedCandidates: Candidate[] = [];
1054	
1055	    //Invert the selection by looking at all candidates, and if they are not currently selected
1056	    //add them to newSelectedCandidates.
1057	    for (const candidate of candidates) {
1058	      //Look for this candidate's id in the currently selected candidates
1059	      if (indexOfHasId(candidate.id, this.selectedCandidates) < 0) {
1060	        //Not in currently selected - so add to new selected.
1061	        newSelectedCandidates.push(candidate);
1062	      }
1063	    }
1064	    //Switch to new selection
1065	    this.selectedCandidates = newSelectedCandidates;
1066	    this.selectedCandidatesChange.emit(this.selectedCandidates);
1067	  }
