43	@Directive()
44	export class CandidateSourceBaseComponent {
45	  error: any = null;
46	  longFormat: boolean;
47	
48	  pageNumber: number;
49	  pageSize: number;
50	  results: SearchResults<Candidate>;
51	  searching: boolean;
52	  sortField: string;
53	  sortDirection: string;
54	  timestamp: number;
55	  reviewStatusFilter: string[] = defaultReviewStatusFilter;
56	
57	  @Input() candidateSource: CandidateSource;
58	
59	  //Temporary - todo to be removed when we no longer use old fetching
60	  useOldFetch: boolean = false;
61	
62	  selectedFields: CandidateFieldInfo[] = [];
63	
64	  constructor(
65	    protected authorizationService: AuthorizationService,
66	    protected candidateSourceResultsCacheService: CandidateSourceResultsCacheService,
67	    protected candidateSourceCandidateService: CandidateSourceCandidateService,
68	    protected candidateFieldService: CandidateFieldService,
69	    protected modalService: NgbModal
70	  ) {}
71	
72	  onSelectColumns() {
73	    //Initialize with current configuration
74	    //Output is new configuration
75	    const modal = this.modalService.open(CandidateColumnSelectorComponent);
76	    modal.componentInstance.setSourceAndFormat(this.candidateSource, this.longFormat);
77	
78	    modal.result
79	    .then(
80	      () => this.loadSelectedFields()
81	    )
82	    .catch(
83	      error => {
84	        if (error !== ModalDismissReasons.ESC) {
85	          this.error = error;
86	        }
87	      });
88	  }
89	
90	  protected loadSelectedFields() {
91	
92	    this.selectedFields = this.candidateFieldService
93	    .getCandidateSourceFields(this.candidateSource, this.longFormat);
94	  }
95	
96	  protected checkCache(refresh: boolean, usePageNumber: boolean = true) {
97	    this.results = null;
98	    this.error = null;
99	
100	    //If already searching just exit.
101	    if (this.searching) {
102	      return;
103	    }
104	
105	    this.searching = true;
106	
107	    let done = false;
108	    if (!refresh) {
109	
110	      //Is there anything in cache?
111	      //We only cache certain results
112	      if (this.isCacheable()) {
113	        const cached: CachedSourceResults =
114	          this.candidateSourceResultsCacheService.getFromCache(this.candidateSource);
115	        if (cached) {
116	          //If we are not required to use the pageNumber (usePageNumber = false)
117	          //we can take the pageNumber of whatever the cache has.
118	          //If we have to use the page number, the pageNumber and size must match
119	          //what is in the cache, or we can't use it.
120	          done = !usePageNumber
121	            || (cached.pageNumber === this.pageNumber && cached.pageSize === this.pageSize);
122	          if (done) {
123	            this.results = cached.results;
124	            this.sortField = cached.sortFields[0];
125	            this.sortDirection = cached.sortDirection;
126	            this.reviewStatusFilter = []; // We don't cache reviewable sources
127	            this.timestamp = cached.timestamp;
128	            this.pageNumber = cached.pageNumber;
129	            this.pageSize = cached.pageSize;
130	            this.searching = false;
131	          }
132	        }
133	      }
134	    }
135	    return done;
136	  }
137	
138	  protected performSearch(
139	    defaultPageSize: number = 12,
140	    dtoType: DtoType = DtoType.EXTENDED,
141	    keyword: string = null,
142	    showClosedOpps: boolean = false
143	  ): Observable<SearchResults<Candidate>> {
144	
145	    this.searching = true;
146	
147	    this.pageNumber = this.pageNumber || 1;
148	    this.pageSize = this.pageSize || defaultPageSize;
149	
150	    //Use candidateSource to default sort based on whether or not there is a query string
151	    let defaultSortField = 'id';
152	    let defaultSortDirection = 'DESC';
153	    if (isSavedSearch(this.candidateSource)) {
154	        if (!isNullOrEmpty(this.candidateSource.simpleQueryString)) {
155	          defaultSortField = 'text_match'
156	        }
157	    }
158	
159	    this.sortField = this.sortField || defaultSortField;
160	    this.sortDirection = this.sortDirection || defaultSortDirection;
161	
162	    //Create the appropriate request
163	    const request = this.createSearchRequest(keyword, showClosedOpps);
164	    request.dtoType = dtoType;
165	
166	    // Return the observable so the caller can subscribe to it
167	    return this.candidateSourceCandidateService.searchPaged(this.candidateSource, request, this.useOldFetch).pipe(
168	      tap(results => {
169	        this.results = results;
170	        this.cacheResults();
171	        this.searching = false;
172	      }),
173	      catchError(error => {
174	        this.error = error;
175	        this.searching = false;
176	        return throwError(error);
177	      })
178	    );
179	  }
180	
181	  createSearchRequest(keyword: string = null, showClosedOpps: boolean = false) {
182	    let request;
183	    if (isSavedSearch(this.candidateSource)) {
184	      const reviewable = this.candidateSource.reviewable;
185	      request = new SavedSearchGetRequest();
186	      if (reviewable) {
187	        request.reviewStatusFilter = this.reviewStatusFilter;
188	      }
189	    } else {
190	      request = new SavedListGetRequest();
191	      request.keyword = keyword;
192	      request.showClosedOpps = showClosedOpps;
193	    }
194	    request.pageNumber = this.pageNumber - 1;
195	    request.pageSize = this.pageSize;
196	    request.sortFields = [this.sortField];
197	    request.sortDirection = this.sortDirection;
198	
199	    return request;
200	  }
201	
202	  private isCacheable(): boolean {
203	    //Reviewable sources are not cacheable because the review filtering makes it too complicated.
204	    return !this.isReviewable();
205	  }
206	
207	  isReviewable(): boolean {
208	    return isSavedSearch(this.candidateSource)
209	      ? this.candidateSource.reviewable : false;
210	  }
211	
212	  protected cacheResults() {
213	    this.timestamp = Date.now();
214	
215	    //We only cache certain results, and we don't cache filter keyword searches
216	    this.candidateSourceResultsCacheService.cache(this.candidateSource, {
217	      id: this.candidateSource.id,
218	      pageNumber: this.pageNumber,
219	      pageSize: this.pageSize,
220	      sortFields: [this.sortField],
221	      sortDirection: this.sortDirection,
222	      results: this.results,
223	      timestamp: this.timestamp
224	    });
225	  }
226	
227	  protected toggleSort(column: string, defaultSortDirection: string = 'ASC') {
228	    if (this.sortField === column) {
229	      this.sortDirection = this.sortDirection === 'ASC' ? 'DESC' : 'ASC';
230	    } else {
231	      this.sortField = column;
232	      this.sortDirection = defaultSortDirection;
233	    }
234	  }
235	
236	  isCvDropDownAvailable(): boolean {
237	    //Employer partners do not see a Cv drop down option in candidate sources.
238	    //They can only see CV's (if authorized) in the candidate display
239	    return !this.authorizationService.isEmployerPartner();
240	  }
241	
242	  isCandidateNameViewable(): boolean {
243	    return this.authorizationService.canViewCandidateName();
244	  }
245	
246	  isCountryViewable(): boolean {
247	    return this.authorizationService.canViewCandidateCountry();
248	  }
249	
250	  sourceType(): string {
251	    return isSavedSearch(this.candidateSource) ? 'savedSearch' : 'list';
252	  }
253	
254	  isExportable(): boolean {
255	    return this.authorizationService.canExportFromSource();
256	  }
257	
258	  isImportable(): boolean {
259	    return isSavedList(this.candidateSource) && this.authorizationService.canImportToList();
260	  }
261	
262	  isPublishable(): boolean {
263	    return isSavedList(this.candidateSource) && this.authorizationService.canPublishList();
264	  }
265	
266	  isStarred(): boolean {
267	    return this.authorizationService.isStarredByMe(this.candidateSource?.users);
268	  }
269	
270	  isJobList(): boolean {
271	    return isSavedList(this.candidateSource) && this.candidateSource.sfJobOpp != null;
272	  }
273	
274	  isSubmissionList(): boolean {
275	    return isSubmissionList(this.candidateSource);
276	  }
277	
278	  isShowStage(): boolean {
279	    return this.isJobList();
280	  }
281	
282	  isEditable(): boolean {
283	    return this.authorizationService.canEditCandidateSource(this.candidateSource);
284	  }
285	
286	  isContentModifiable(): boolean {
287	    let modifiable = false;
288	    if (!isSavedSearch(this.candidateSource)) {
289	      if (this.authorizationService.isCandidateSourceMine(this.candidateSource)) {
290	        modifiable = true
291	      } else {
292	        modifiable = !this.authorizationService.isReadOnly();
293	      }
294	    }
295	    return modifiable;
296	  }
297	
298	  canAccessSalesforce(): boolean {
299	    return this.authorizationService.canAccessSalesforce();
300	  }
301	
302	  canAccessGoogleDrive(): boolean {
303	    return this.authorizationService.canAccessGoogleDrive();
304	  }
305	
306	  isSalesforceUpdatable(): boolean {
307	    //Employer partners can't update Salesforce from a candidate source - only from each
308	    //candidate's display (assuming that they authorized to).
309	    return !isSavedSearch(this.candidateSource) && !this.authorizationService.isEmployerPartner()
310	      && this.authorizationService.canUpdateSalesforce() && this.isContentModifiable();
311	  }
312	
313	  canAssignTasks() {
314	    return this.authorizationService.canAssignTask();
315	  }
316	
317	  canUpdateStatuses() {
318	    return this.isContentModifiable() && this.authorizationService.canUpdateCandidateStatus();
319	  }
320	
321	  canResolveTasks(): boolean {
322	    //Employer partners can't resolve outstanding candidate tasks from a list
323	    return isSavedList(this.candidateSource) && !this.authorizationService.isEmployerPartner()
324	    && this.authorizationService.canManageCandidateTasks();
325	  }
326	
327	
328	  getCandidateOpportunityLink(candidate: Candidate): any[] {
329	    const opp = this.getCandidateOppForThisJob(candidate);
330	    return opp ? ['/opp', opp.id] : null;
331	  }
332	
333	  /**
334	   * Get candidate opportunity matching current job
335	   * @param candidate Candidate who opportunities we need to search
336	   */
337	  getCandidateOppForThisJob(candidate: Candidate): CandidateOpportunity {
338	    return candidate.candidateOpportunities.find(o => o.jobOpp.id === this.candidateSource.sfJobOpp?.id);
339	  }
340	
341	  isShareable(): boolean {
342	    let shareable: boolean = false;
343	
344	    //Is shareable with me if it is not created by me.
345	    if (this.candidateSource) {
346	      //was it created by me?
347	      if (!this.authorizationService.isCandidateSourceMine(this.candidateSource)) {
348	        shareable = true;
349	      }
350	    }
351	    return shareable;
352	  }
353	
354	  isGlobal(): boolean {
355	    return this.candidateSource.global;
356	  }
357	
358	}
