17	import {Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges} from '@angular/core';
18	import {getCandidateSourceNavigation} from '../../../../model/saved-search';
19	import {Router} from '@angular/router';
20	import {
21	  CandidateSourceResultsCacheService
22	} from '../../../../services/candidate-source-results-cache.service';
23	import {CandidateSource, DtoType} from '../../../../model/base';
24	import {CandidateSourceCandidateService} from '../../../../services/candidate-source-candidate.service';
25	import {AuthorizationService} from '../../../../services/authorization.service';
26	import {CandidateFieldService} from "../../../../services/candidate-field.service";
27	import {NgbModal} from "@ng-bootstrap/ng-bootstrap";
28	import {CandidateSourceBaseComponent} from "../candidate-source-base";
29	
30	@Component({
31	  selector: 'app-candidate-source-results',
32	  templateUrl: './candidate-source-results.component.html',
33	  styleUrls: ['./candidate-source-results.component.scss']
34	})
35	export class CandidateSourceResultsComponent extends CandidateSourceBaseComponent implements OnInit, OnChanges {
36	  @Input() showSourceDetails = true;
37	  @Output() toggleStarred = new EventEmitter<CandidateSource>();
38	  @Output() toggleWatch = new EventEmitter<CandidateSource>();
39	  @Output() copySource = new EventEmitter<CandidateSource>();
40	  @Output() deleteSource = new EventEmitter<CandidateSource>();
41	  @Output() editSource = new EventEmitter<CandidateSource>();
42	
43	  constructor(
44	      private router: Router,
45	      protected authorizationService: AuthorizationService,
46	      protected candidateSourceResultsCacheService: CandidateSourceResultsCacheService,
47	      protected candidateSourceCandidateService: CandidateSourceCandidateService,
48	      protected candidateFieldService: CandidateFieldService,
49	      protected modalService: NgbModal
50	    ) {
51	      super(
52	        authorizationService,
53	        candidateSourceResultsCacheService,
54	        candidateSourceCandidateService,
55	        candidateFieldService,
56	        modalService);
57	  };
58	
59	  ngOnInit() {
60	    this.longFormat = false;
61	  }
62	
63	  ngOnChanges(changes: SimpleChanges): void {
64	    //Do search if candidate source has changed.
65	    const change = changes.candidateSource;
66	    if (change && change.previousValue !== change.currentValue) {
67	      this.loadSelectedFields();
68	      this.search(false);
69	    }
70	  }
71	
72	  onOpenSource() {
73	    //Open source at same page number
74	    let extras;
75	    if (this.pageNumber === 1) {
76	      extras = {};
77	    } else {
78	      extras = {queryParams: {pageNumber: this.pageNumber}};
79	    }
80	    const urlCommands = getCandidateSourceNavigation(this.candidateSource);
81	    this.router.navigate(urlCommands, extras);
82	  }
83	
84	  search(refresh: boolean) {
85	    let done = this.checkCache(refresh, false);
86	    if (!done) {
87	      // Keep page size smaller for this component (12). It is a preview of the source, so doesn't
88	      // need to be long.
89	      // It works better on all screen sizes, especially when we have a long split page.
90	      this.performSearch(12, DtoType.PREVIEW).subscribe();
91	    }
92	  }
93	
94	  toggleSort(column: string) {
95	    super.toggleSort(column);
96	    this.search(true);
97	  }
98	
99	  //Pass toggle starred up to BrowseCandidateSourcesComponent for it to
100	  //do the update and refresh its copy of the candidate source details
101	  // (which is passed through to all contained components)
102	  onToggleStarred(source: CandidateSource) {
103	    this.toggleStarred.emit(source);
104	  }
105	
106	  //Pass toggle watch up to BrowseCandidateSourcesComponent for it to
107	  //do the update and refresh its copy of the candidate source details
108	  // (which is passed through to all contained components)
109	  onToggleWatch(source: CandidateSource) {
110	    this.toggleWatch.emit(source);
111	  }
112	
113	  onDeleteSource(source: CandidateSource) {
114	    this.deleteSource.emit(source);
115	  }
116	
117	  onEditSource(source: CandidateSource) {
118	    this.editSource.emit(source);
119	  }
120	
121	  onCopySource(source: CandidateSource) {
122	    this.copySource.emit(source);
123	  }
124	
125	  onPageChange() {
126	    this.search(true);
127	  }
128	
129	  onRefreshRequest() {
130	    this.search(true);
131	  }
132	
133	}
