73	})
74	export class BrowseCandidateSourcesComponent implements OnInit, OnChanges {
75	
76	  private filterKeySuffix: string = 'Filter';
77	  private savedStateKeyPrefix: string = 'BrowseKey';
78	
79	  @Input() sourceType: CandidateSourceType;
80	  @Input() searchBy: SearchBy;
81	  @Input() savedSearchType: SavedSearchType;
82	  @Input() savedSearchSubtype: SavedSearchSubtype;
83	  @Input() savedSearchTypeSubInfos: SavedSearchTypeSubInfo[];
84	  @Output() subtypeChange = new EventEmitter<SavedSearchTypeSubInfo>();
85	
86	  searchForm: UntypedFormGroup;
87	  public loading: boolean;
88	  error: any;
89	  pageNumber: number;
90	  pageSize: number;
91	  results: SearchResults<CandidateSource>;
92	  selectedSource: CandidateSource;
93	  selectedIndex = 0;
94	  loggedInUser: User;
95	  stages = enumOptions(JobOpportunityStage);
96	
97	  readonly CandidateSourceType = CandidateSourceType;
98	
99	  constructor(private fb: UntypedFormBuilder,
100	              private localStorageService: LocalStorageService,
101	              private router: Router,
102	              private authorizationService: AuthorizationService,
103	              private authenticationService: AuthenticationService,
104	              private modalService: NgbModal,
105	              private candidateSourceResultsCacheService: CandidateSourceResultsCacheService,
106	              private candidateSourceService: CandidateSourceService,
107	              public salesforceService: SalesforceService,
108	              private savedSearchService: SavedSearchService) {
109	  }
110	
111	  ngOnInit() {
112	
113	    this.loggedInUser = this.authenticationService.getLoggedInUser();
114	
115	    //Pick up any previous keyword filter
116	    const filter = this.localStorageService.get(this.savedStateKey() + this.filterKeySuffix);
117	    this.searchForm = this.fb.group({
118	      keyword: [filter],
119	      selectedStages: [["candidateSearch"]]
120	    });
121	    this.pageNumber = 1;
122	    this.pageSize = 30;
123	
124	    this.subscribeToFilterChanges();
125	    this.search();
126	  }
127	
128	  get keyword(): string {
129	    return this.searchForm ? this.searchForm.value.keyword : "";
130	  }
131	
132	  get selectedStages(): string[] {
133	    return this.searchForm ? this.searchForm.value.selectedStages : "";
134	  }
135	
136	  ngOnChanges(changes: SimpleChanges): void {
137	    if (this.sourceType === CandidateSourceType.SavedSearch) {
138	      //We want to catch changes of sub type (eg Professions/Business to Professions/Healthcare)
139	      if (changes.savedSearchSubtype) {
140	        //The very first call of this is before ngOnInit. See https://angular.io/guide/lifecycle-hooks
141	        //We only want to catch changes after we have started the component.
142	        if (!changes.savedSearchSubtype.isFirstChange()) {
143	          //Pick up filter for this new sub type and update search
144	          const filter = this.localStorageService.get(this.savedStateKey() + this.filterKeySuffix);
145	          this.searchForm?.controls['keyword'].patchValue(filter);
146	          this.search();
147	        }
148	      }
149	    }
150	  }
151	
152	  getBrowserDisplayString(source: CandidateSource) {
153	    let s = source.name;
154	    if (this.searchBy === SearchBy.registeredJob) {
155	      if (isSavedList(source)) {
156	        s += "(" + source.sfJobCountry + ") - " + source.sfJobStage;
157	      }
158	    }
159	    return s;
160	  }
161	
162	  subscribeToFilterChanges(): void {
163	    this.searchForm.valueChanges
164	      .pipe(
165	        debounceTime(400),
166	        distinctUntilChanged()
167	      )
168	      .subscribe(() => {
169	        this.search();
170	      });
171	  }
