173	  search() {
174	
175	    //Remember keyword filter from last search
176	    this.localStorageService.set(this.savedStateKey() + this.filterKeySuffix, this.keyword);
177	
178	    let req;
179	    switch (this.sourceType) {
180	      case CandidateSourceType.SavedSearch:
181	        req = new SearchSavedSearchRequest();
182	        break;
183	
184	      case CandidateSourceType.SavedList:
185	        req = new SearchSavedListRequest();
186	        break;
187	    }
188	
189	    req.keyword = this.keyword;
190	    req.pageNumber = this.pageNumber - 1;
191	    req.pageSize = this.pageSize;
192	
193	    //These are lists and searches (ie not CandidateSourceType.Job's)
194	    //Default sort for them is alpha
195	    req.sortFields = ['name'];
196	    req.sortDirection = 'ASC';
197	    req.dtoType = DtoType.MINIMAL;
198	
199	    switch (this.searchBy) {
200	      case SearchBy.mine:
201	        req.owned = true;
202	        break;
203	      case SearchBy.sharedWithMe:
204	        req.shared = true;
205	        break;
206	      case SearchBy.watched:
207	        req.watched = true;
208	        break;
209	      case SearchBy.all:
210	        req.global = true;
211	        req.owned = true;
212	        req.shared = true;
213	        break;
214	      case SearchBy.externalLink:
215	        req.shortName = true;
216	        break;
217	      case SearchBy.registeredJob:
218	        req.registeredJob = true;
219	        break;
220	    }
221	    if (this.savedSearchType !== undefined) {
222	      if (req instanceof SearchSavedSearchRequest) {
223	        req.savedSearchType = this.savedSearchType;
224	        req.savedSearchSubtype = this.savedSearchSubtype;
225	        req.global = true;
226	        req.owned = true;
227	        req.shared = true;
228	      }
229	    }
230	
231	    this.loading = true;
232	
233	    this.candidateSourceService.searchPaged(this.sourceType, req).subscribe(results => {
234	      this.results = results;
235	
236	      if (results.content.length > 0) {
237	        //Selected previously search if any
238	        const id: number = this.localStorageService.get(this.savedStateKey());
239	        if (id) {
240	          this.selectedIndex = indexOfHasId(id, this.results.content);
241	          if (this.selectedIndex >= 0) {
242	            this.selectedSource = this.results.content[this.selectedIndex];
243	          } else {
244	            //Select the first search if can't find previous (category of search
245	            // may have changed)
246	            this.select(this.results.content[0]);
247	          }
248	        } else {
249	          //Select the first search if no previous
250	          this.select(this.results.content[0]);
251	        }
252	      }
253	
254	      this.loading = false;
255	    },
256	    error => {
257	      this.error = error;
258	      this.loading = false;
259	    });
260	  }
