262	  /**
263	   * Called when a particular source (ie list or search) is selected from browse results
264	   * of the search of sources.
265	   * @param source Selected candidate source
266	   */
267	  select(source: CandidateSource) {
268	    this.selectedSource = source;
269	
270	    const id: number = source.id;
271	    this.localStorageService.set(this.savedStateKey(), id);
272	
273	    this.selectedIndex = indexOfHasId(id, this.results.content);
