276	  private savedStateKey() {
277	    //This key is constructed from the combination of inputs which are associated with each tab
278	    // in home.component.html
279	    //This key is used to store the last state associated with each tab.
280	
281	    //The standard key is "BrowseKey" + the sourceType (SavedSearch or SaveList) +
282	    // the search by (corresponding to the specific displayed tab)
283	    let key = this.savedStateKeyPrefix
284	      + CandidateSourceType[this.sourceType]
285	      + SearchBy[this.searchBy];
286	
287	    //If searching by type, also need the saved search type
288	    if (this.searchBy === SearchBy.type && this.savedSearchType != null) {
289	      key += this.savedSearchType +
290	        (this.savedSearchSubtype != null ? '/' + this.savedSearchSubtype : "");
291	    }
292	    return key;
293	  }
