295	  keyDown(event: KeyboardEvent) {
296	    const oldSelectedIndex = this.selectedIndex;
297	    switch (event.key) {
298	      case 'ArrowUp':
299	        if (this.selectedIndex > 0) {
300	          this.selectedIndex--;
301	        }
302	        break;
303	      case 'ArrowDown':
304	        if (this.selectedIndex < this.results.content.length - 1) {
305	          this.selectedIndex++;
306	        }
307	        break;
308	    }
309	    if (this.selectedIndex !== oldSelectedIndex) {
310	      this.select(this.results.content[this.selectedIndex])
311	    }
312	  }
