490	  private updateLocalCandidateSourceCopy(source: CandidateSource) {
491	    //Looking at lists or searches.
492	    //Need to update the list of sources as well as the currently selected source if that
493	    //is the source which has been updated
494	    const index: number = indexOfHasId(source.id, this.results.content);
