1	import {Component, EventEmitter, Input, Output, ViewEncapsulation} from '@angular/core';
2	import {SearchResults} from "../../../model/search-results";
3	
4	/**
5	 * @component TcTableComponent
6	 * @description
7	 * A reusable table wrapper component that contains both the table and pagination UI.
8	 *
9	 * **Features:**
10	 * - Displays and styles a data table
11	 * - Integrates pagination controls
12	 * - Wraps the `<thead>` and `<tbody>` markup, allowing customization
13	 *   (e.g., icons, popovers, chat read statuses)
14	 *
15	 * @selector tc-table
16	 *
17	 *  **Inputs**
18	 *  - `results: SearchResults<any> | any[]` — data source for the table
19	 *  - `loading: boolean` — toggles loading state
20	 *  - `name: string` — optional title displayed above the table**
21	 *  - `striped: boolean` — enables Bootstrap striped table style**
22	 *  - `hover: boolean` — enables hover styling on rows**
23	 *  - `paginationPosition: 'top' | 'bottom'` — where pagination appears**
24	 *  - `clickableRows: boolean` — toggles `.clickable-rows` class**
25	 *  - `pageNumber: number` — current page (required for paged data)**
26	 *
27	 * **Outputs**
28	 *  - `pageNumberChange: EventEmitter<number>` — enables two-way binding for `[(pageNumber)]`**
29	 *  - `pageChange: EventEmitter<void>` — fired after pageNumber changes**
30	 *
31	 * @example
32	 * ```html
33	 * <tc-table
34	 *   name="My Paged Search Results"
35	 *   [results]="results"
36	 *   [loading]="loading"
37	 *   [(pageNumber)]="pageNumber"
38	 *   (pageChange)="search()">
39	 * </tc-table>
40	 * ```
41	 */
42	@Component({
43	  selector: 'tc-table',
44	  templateUrl: './tc-table.component.html',
45	  styleUrls: ['./tc-table.component.scss'],
46	  // Setting to None means the tc-table scss style only applies styles to <table> elements within the tc-table component,
47	  // avoids styles bleeding out to the other <table> components not wrapped by <tc-table>. Also overrides any
48	  // existing <table> styles from bootstrap.
49	  encapsulation: ViewEncapsulation.None
50	})
51	export class TcTableComponent {
52	  // Required inputs
53	  /** Knowing the results allows the table to display a 'no results' warning if no results appear
54	   * (e.g. in a table search).
55	   * For paged search results passing them in allows the table to include the pagination feature.
56	   */
57	  @Input() results: SearchResults<any> | any[];
58	  @Input() loading: boolean = false;
59	
60	  // Optional style inputs
61	  @Input() name: string;
62	  @Input() striped: boolean = false;
63	  @Input() hover: boolean = true;
64	  // Optional if pagination supported
65	  @Input() paginationPosition: 'top' | 'bottom' | 'both' = 'bottom';
66	  /** Pass false when rows are not intended to be clickable e.g. to display a summary card */
67	  @Input() clickableRows: boolean = true;
68	
69	  // Required inputs IF results are paged to support pagination
70	  @Input() pageNumber: number;
71	  @Output() pageNumberChange = new EventEmitter<number>();
72	  @Output() pageChange = new EventEmitter();
73	
74	  get classList() {
75	    return {
76	      'clickable-rows': this.clickableRows,
77	      'table-striped': this.striped,
78	      'table-hover': this.hover
79	    };
80	  }
81	
82	  get totalElements(): number {
83	    if (!this.results) {
84	      return 0;
85	    }
86	
87	    if (Array.isArray(this.results)) {
88	      return this.results.length;
89	    }
90	
91	    return this.results.totalElements;
92	  }
93	
94	  get pageSize(): number | null {
95	    if (!this.results || Array.isArray(this.results)) {
96	      return null;
97	    }
98	
99	    return this.results.size;
100	  }
101	
102	  get hasResults(): boolean {
103	    return !!this.results;
104	  }
105	
106	  get noResults(): boolean {
107	    if (!this.results) {
108	      return false;
109	    }
110	
111	    if (Array.isArray(this.results)) {
112	      return this.results.length === 0;
113	    }
114	
115	    return this.results.totalElements === 0;
116	  }
117	
118	  get isPagedResults(): boolean {
119	    if (!this.results) {
120	      return false;
121	    }
122	
123	    return !Array.isArray(this.results);
124	  }
125	
126	  onPageChange(newPageNumber: number) {
127	    this.pageNumber = newPageNumber;
128	    // Emit the pageNumberChange so I can use two way binding on pageNumber
129	    this.pageNumberChange.emit(newPageNumber);
130	    // Emit the pageChange event so I can do an action on the page change e.g. Search
131	    this.pageChange.emit();
132	  }
133	
134	}
