34	/**
35	 * Service for caching the results returned by candidate sources.
36	 * <p/>
37	 * Once set of results is cached for each candidate source.
38	 * The cached results are associated with a standard filtering
39	 * (by page number/size, sorting and sort order)
40	 */
41	@Injectable({
42	  providedIn: 'root'
43	})
44	export class CandidateSourceResultsCacheService {
45	
46	  constructor(
47	    private localStorageService: LocalStorageService
48	  ) { }
49	
50	  private static cacheKey(source: CandidateSource): string {
51	    return getCandidateSourceType(source) + source.id;
52	  }
53	
54	  /**
55	   * Cache the given results associated with the given source.
56	   * @param source Candidate source associated with results.
57	   * @param cachedSearchResults Results to be stored in cache.
58	   */
59	  cache(source: CandidateSource, cachedSearchResults: CachedSourceResults): void {
60	    const cacheKey = CandidateSourceResultsCacheService.cacheKey(source);
61	    this.localStorageService.set(cacheKey, cachedSearchResults);
62	  }
63	
64	  /**
65	   * Returns the cached results associated with the given source.
66	   * <p/>
67	   * Note that it is up to the caller to ensure that the given page number,
68	   * sort and any other requested filtering is what is required.
69	   * <p/>
70	   * In particular, note that reviewable SavedSearch's have review filters which affect
71	   * the returned results (in addition to the standard paging and sorting).
72	   * This common caching does not take into account review filtering so
73	   * caching should be turned off for reviewable searches.
74	   * @param source Candidate source whose cache is requested
75	   * @return Cached results or null if none found.
76	   */
77	  getFromCache(source: CandidateSource): CachedSourceResults | null {
78	    const cacheKey = CandidateSourceResultsCacheService.cacheKey(source);
79	    return this.localStorageService.get<CachedSourceResults>(cacheKey);
80	  }
81	
82	  /**
83	   * Remove the cached info associated with the given source.
84	   * <p/>
85	   * This ensures that the next request for results from this source will
86	   * not come from the cache.
87	   * @param source Candidate source whose cache is to be cleared.
88	   */
89	  removeFromCache(source: CandidateSource): void {
90	    const cacheKey = CandidateSourceResultsCacheService.cacheKey(source);
91	    this.localStorageService.remove(cacheKey);
92	  }
93	}
